(function() {
    'use strict';

    class LiquidityStressAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'LiquidityStress';
            this.version = '1.1.0';

            this.BANK = {
                totalAssets: 50000,
                hqlaL1: 6000,
                hqlaL2a: 2500,
                hqlaL2b: 1500,
                adjHQLA: 8875,
                loans: 15000,
                securities: 12500,
                interbankAssets: 7500,
                otherAssets: 5000,
                retailDeposits: 18400,
                wholesaleFunding: 11500,
                repoFunding: 9200,
                interbankLiab: 4600,
                otherLiab: 2300,
                capital: 4000,
                baseOutflows: 7521,
                baseASF: 43050,
                baseRSF: 41000
            };

            this.ROUNDS = [
                {
                    phase: 'Phase 1: Baseline Assessment',
                    phaseShort: 'Baseline',
                    description: 'Welcome to the Treasury desk. You are reviewing the liquidity position of a mid-sized European commercial bank with total assets of €50 billion.<br><br><strong>Your bank profile:</strong><br>• Assets: 30% loans, 25% securities, 20% HQLA, 15% interbank, 10% other<br>• Liabilities: 40% retail deposits, 25% wholesale funding, 20% repo, 10% interbank, 5% other<br>• Capital: €4B (Tier 1 ratio 8.5%)<br>• LCR: 118% | NSFR: 105%<br><br>Examine the dashboard carefully. <strong>Identify the most significant vulnerability</strong> in the bank balance sheet.',
                    inputType: 'select',
                    options: [
                        { value: 1, text: 'LCR buffer is thin (only 18% above minimum)' },
                        { value: 2, text: 'Funding concentration risk (heavy wholesale and repo reliance)' },
                        { value: 3, text: 'HQLA quality (significant Level 2B holdings)' },
                        { value: 4, text: 'Maturity mismatch (short-term funding for long-term assets)' }
                    ]
                },
                {
                    phase: 'Phase 2: Deposit Run',
                    phaseShort: 'Deposit Run',
                    description: 'A rumor about loan losses spreads on social media. Retail depositors begin withdrawing funds. Unlike 2007, digital banking means withdrawals happen in hours, not days (recall SVB lost $42 billion in a single day).<br><br>Set the <strong>deposit outflow rate</strong> to simulate the run severity. At 10%, approximately €1.84 billion leaves the bank in 30 days. At 20%, €3.68 billion.',
                    inputType: 'range',
                    min: 5,
                    max: 25,
                    step: 1,
                    defaultVal: 10,
                    unit: '%',
                    inputLabel: 'Retail Deposit Outflow Rate'
                },
                {
                    phase: 'Phase 3: Wholesale Funding Freeze',
                    phaseShort: 'Wholesale Freeze',
                    description: 'Interbank and institutional lenders refuse to roll over maturing wholesale funding. Commercial paper markets are closed. The bank cannot issue new unsecured debt.<br><br>This is what happened to Northern Rock in 2007 — the wholesale market shut overnight. Set the <strong>percentage of wholesale funding that is frozen</strong>.',
                    inputType: 'range',
                    min: 0,
                    max: 100,
                    step: 5,
                    defaultVal: 50,
                    unit: '%',
                    inputLabel: 'Wholesale Funding Freeze Rate'
                },
                {
                    phase: 'Phase 4: Collateral Shock',
                    phaseShort: 'Collateral Shock',
                    description: 'A broad market selloff triggers a repricing of collateral values. Corporate bond spreads widen and equity indices fall. Repo counterparties demand higher haircuts, reducing the effective value of Level 2A and Level 2B HQLA.<br><br>This is the Brunnermeier-Pedersen liquidity spiral: falling prices → higher haircuts → less funding → forced sales → further price drops.<br><br>Set the <strong>additional haircut</strong> applied to Level 2 HQLA.',
                    inputType: 'range',
                    min: 5,
                    max: 30,
                    step: 1,
                    defaultVal: 15,
                    unit: '%',
                    inputLabel: 'Additional Haircut on Level 2 HQLA'
                },
                {
                    phase: 'Phase 5: Rating Downgrade',
                    phaseShort: 'Rating Downgrade',
                    description: 'A credit rating agency downgrades the bank. Each notch triggers contractual clauses: additional collateral posting requirements, early termination of derivative contracts, and loss of access to certain funding markets.<br><br>Credit Suisse experienced this in 2022-2023 — downgrades accelerated the outflow spiral. Set the <strong>number of notches</strong> for the downgrade.',
                    inputType: 'range',
                    min: 1,
                    max: 3,
                    step: 1,
                    defaultVal: 2,
                    unit: ' notches',
                    inputLabel: 'Rating Downgrade Severity'
                },
                {
                    phase: 'Phase 6: Combined Stress Test',
                    phaseShort: 'Combined Stress',
                    description: 'Now apply <strong>all four stresses simultaneously</strong>. In real crises, shocks never come alone — deposit runs trigger rating downgrades, which trigger wholesale freezes, which trigger collateral calls.<br><br>The combined stress applies an <strong>amplification factor</strong> that models the non-linear interaction between stress channels. A higher factor represents stronger contagion between stress types.<br><br>Observe how quickly LCR can breach regulatory minimums when stresses compound.',
                    inputType: 'range',
                    min: 100,
                    max: 200,
                    step: 5,
                    defaultVal: 130,
                    unit: '%',
                    inputLabel: 'Stress Amplification Factor'
                },
                {
                    phase: 'Phase 7: Contingency Funding Plan',
                    phaseShort: 'Contingency',
                    description: 'The LCR has breached 100%. As Treasury head, you must activate the Contingency Funding Plan (CFP). Each action has trade-offs:<br><br>• <strong>Sell Securities Portfolio:</strong> +€2B HQLA, but lose future income and signal distress<br>• <strong>Central Bank Facility:</strong> +€3B liquidity, reduces outflows, but signals severe distress to markets<br>• <strong>Reduce New Lending:</strong> reduces outflows by €1.5B, but damages client relationships and franchise value<br>• <strong>Emergency Asset Sale:</strong> +€4B immediate liquidity, but at 20% discount (fire-sale pricing)<br><br>Choose the <strong>primary contingency action</strong> you would recommend.',
                    inputType: 'select',
                    options: [
                        { value: 1, text: 'Sell securities portfolio (+€2B HQLA)' },
                        { value: 2, text: 'Draw central bank emergency facility (+€3B, -€1B outflows)' },
                        { value: 3, text: 'Reduce new lending commitments (-€1.5B outflows)' },
                        { value: 4, text: 'Emergency asset fire-sale (+€4B at 20% loss)' }
                    ]
                },
                {
                    phase: 'Phase 8: Final Assessment',
                    phaseShort: 'Assessment',
                    description: 'Review the full trajectory of the bank through the stress scenarios. Consider these questions:<br><br>• At what point did the bank breach regulatory minimums?<br>• Which single stress had the largest impact on LCR?<br>• How did the combined stress compare to the sum of individual stresses?<br>• Was the contingency action sufficient to restore compliance?<br><br>Select the <strong>most critical lesson</strong> from this exercise.',
                    inputType: 'select',
                    options: [
                        { value: 1, text: 'Liquidity risk is primarily about time — a solvent bank can fail in days' },
                        { value: 2, text: 'Funding diversification is the single most important defense' },
                        { value: 3, text: 'Stress interactions are non-linear — combined impact exceeds the sum of parts' },
                        { value: 4, text: 'Contingency plans must be pre-arranged — you cannot negotiate during a crisis' }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    currentHQLA: 8875,
                    currentOutflows: 7521,
                    currentASF: 43050,
                    currentRSF: 41000,
                    lcr: 118,
                    nsfr: 105,
                    depositRunPct: 0,
                    wholesaleFreezePct: 0,
                    collateralShockPct: 0,
                    ratingNotches: 0,
                    amplificationPct: 100,
                    contingencyAction: 0,
                    lcrHistory: [],
                    nsfrHistory: [],
                    scoreHistory: [],
                    totalScore: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    action: 0
                };
            }
            this._updateBriefing(state);
            this._updateDashboard(state.domainState);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = round.phase;

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = round.description;

            var area = document.getElementById('decisionArea');
            if (!area) return;

            var html = '';
            if (round.inputType === 'select') {
                html += '<label for="actionInput">' + window.mySimulation.t('choose_label') + '</label>';
                html += '<select id="actionInput">';
                for (var i = 0; i < round.options.length; i++) {
                    var opt = round.options[i];
                    html += '<option value="' + opt.value + '">' + opt.text + '</option>';
                }
                html += '</select>';
            } else if (round.inputType === 'range') {
                html += '<label for="actionInput">' + round.inputLabel + '</label>';
                html += '<div class="liquidity-sim-severity-display" id="severityVal">' + round.defaultVal + round.unit + '</div>';
                html += '<input type="range" id="actionInput" min="' + round.min + '" max="' + round.max + '" step="' + round.step + '" value="' + round.defaultVal + '"';
                html += ' oninput="document.getElementById(\'severityVal\').textContent = this.value + \'' + round.unit + '\'">';
            }
            area.innerHTML = html;
        }

        _updateDashboard(ds) {
            var B = this.BANK;
            var hqlaL1 = B.hqlaL1;
            var adjL2a = B.hqlaL2a * (1 - (0.15 + (ds.collateralShockPct || 0) / 100));
            var adjL2b = Math.max(0, B.hqlaL2b * (1 - (0.50 + (ds.collateralShockPct || 0) / 100)));

            var hqlaEl = document.getElementById('hqlaBreakdown');
            if (hqlaEl) {
                var totalH = hqlaL1 + adjL2a + adjL2b;
                var maxH = 10000;
                hqlaEl.innerHTML =
                    this._barRow('Level 1', hqlaL1, maxH, '#4ecdc4', hqlaL1) +
                    this._barRow('Level 2A', Math.round(adjL2a), maxH, '#45b7d1', Math.round(adjL2a)) +
                    this._barRow('Level 2B', Math.round(adjL2b), maxH, '#f39c12', Math.round(adjL2b));
            }

            var fundEl = document.getElementById('fundingBreakdown');
            if (fundEl) {
                var maxF = 20000;
                var retDep = B.retailDeposits - B.retailDeposits * (ds.depositRunPct || 0) / 100;
                var worF = B.wholesaleFunding * (1 - (ds.wholesaleFreezePct || 0) / 100);
                fundEl.innerHTML =
                    this._barRow('Retail Dep.', Math.round(retDep), maxF, '#4ecdc4', Math.round(retDep)) +
                    this._barRow('Wholesale', Math.round(worF), maxF, '#e74c3c', Math.round(worF)) +
                    this._barRow('Repo', B.repoFunding, maxF, '#f39c12', B.repoFunding) +
                    this._barRow('Interbank', B.interbankLiab, maxF, '#45b7d1', B.interbankLiab);
            }
        }

        _barRow(label, value, maxVal, color, displayVal) {
            var pct = Math.min(100, Math.round(value / maxVal * 100));
            return '<div class="liquidity-sim-bar-row">' +
                '<span class="liquidity-sim-bar-label">' + label + '</span>' +
                '<div class="liquidity-sim-bar-track"><div class="liquidity-sim-bar-fill" style="width:' + pct + '%;background:' + color + ';"></div></div>' +
                '<span class="liquidity-sim-bar-value">€' + Math.round(displayVal).toLocaleString() + 'M</span>' +
                '</div>';
        }

        _recalcMetrics(ds) {
            var B = this.BANK;
            var hqla = B.adjHQLA;
            var outflows = B.baseOutflows;
            var asf = B.baseASF;
            var rsf = B.baseRSF;

            if (ds.depositRunPct > 0) {
                outflows += B.retailDeposits * ds.depositRunPct / 100;
                asf -= 0.9 * B.retailDeposits * ds.depositRunPct / 100;
            }
            if (ds.wholesaleFreezePct > 0) {
                outflows += B.wholesaleFunding * ds.wholesaleFreezePct / 100;
                asf -= 0.5 * B.wholesaleFunding * ds.wholesaleFreezePct / 100;
            }
            if (ds.collateralShockPct > 0) {
                var newL2a = B.hqlaL2a * (1 - (0.15 + ds.collateralShockPct / 100));
                var newL2b = Math.max(0, B.hqlaL2b * (1 - (0.50 + ds.collateralShockPct / 100)));
                hqla = B.hqlaL1 + newL2a + newL2b;
                outflows += (B.adjHQLA - hqla) * 0.3;
            }
            if (ds.ratingNotches > 0) {
                outflows += 1500 * ds.ratingNotches;
                asf -= 500 * ds.ratingNotches;
            }

            if (ds.amplificationPct > 100) {
                var amp = ds.amplificationPct / 100;
                var outflowDelta = outflows - B.baseOutflows;
                var hqlaDelta = B.adjHQLA - hqla;
                var asfDelta = B.baseASF - asf;
                outflows = B.baseOutflows + outflowDelta * amp;
                hqla = B.adjHQLA - hqlaDelta * amp;
                asf = B.baseASF - asfDelta * amp;
            }

            if (ds.contingencyAction === 1) {
                hqla += 2000;
            } else if (ds.contingencyAction === 2) {
                hqla += 3000;
                outflows -= 1000;
            } else if (ds.contingencyAction === 3) {
                outflows -= 1500;
            } else if (ds.contingencyAction === 4) {
                hqla += 4000;
            }

            hqla = Math.max(0, hqla);
            outflows = Math.max(1, outflows);
            asf = Math.max(0, asf);
            rsf = Math.max(1, rsf);

            ds.currentHQLA = Math.round(hqla);
            ds.currentOutflows = Math.round(outflows);
            ds.currentASF = Math.round(asf);
            ds.currentRSF = rsf;
            ds.lcr = Math.round(hqla / outflows * 100);
            ds.nsfr = Math.round(asf / rsf * 100);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var input = document.getElementById('actionInput');
            if (input) {
                decisions.action = parseFloat(input.value);
            }
            if (decisions.action === undefined || isNaN(decisions.action)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('action_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var round = this.ROUNDS[Math.min(period - 1, this.ROUNDS.length - 1)];
            var score = 0;

            switch(period) {
                case 1:
                    score = (d.action === 2) ? 15 : (d.action === 4) ? 12 : (d.action === 1) ? 8 : 6;
                    break;
                case 2:
                    ds.depositRunPct = d.action;
                    score = 10;
                    break;
                case 3:
                    ds.wholesaleFreezePct = d.action;
                    score = 10;
                    break;
                case 4:
                    ds.collateralShockPct = d.action;
                    score = 10;
                    break;
                case 5:
                    ds.ratingNotches = d.action;
                    score = 10;
                    break;
                case 6:
                    ds.amplificationPct = d.action;
                    this._recalcMetrics(ds);
                    var combinedLcr = ds.lcr;
                    score = (combinedLcr < 50) ? 15 : (combinedLcr < 75) ? 12 : 8;
                    break;
                case 7:
                    ds.contingencyAction = d.action;
                    this._recalcMetrics(ds);
                    score = (ds.lcr >= 90) ? 18 : (ds.lcr >= 70) ? 14 : 10;
                    break;
                case 8:
                    score = (d.action === 3) ? 15 : (d.action === 1) ? 13 : (d.action === 4) ? 12 : 10;
                    break;
            }

            this._recalcMetrics(ds);

            ds.totalScore += score;
            ds.lcrHistory.push(ds.lcr);
            ds.nsfrHistory.push(ds.nsfr);
            ds.scoreHistory.push(score);

            // v1.1.0: expose a 0-100 overall (score / performance.overallScore) for the
            // grading/reporting layer, tied to the sim's own totalScore tiers.
            var _overall = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            var _rating = 'Needs Improvement';
            if (ds.totalScore >= 85) _rating = 'Excellent';
            else if (ds.totalScore >= 70) _rating = 'Good';
            else if (ds.totalScore >= 55) _rating = 'Developing';
            ds.score = _overall;
            ds.performance = { overallScore: _overall, rating: _rating, rawScore: ds.totalScore };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                self._updateDashboard(ds);
