        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.phaseScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var lcrValues = history.map(function(r) { return r.results ? r.results.lcrAfter || 0 : 0; });
            var minLcr = Math.min.apply(null, lcrValues);
            var finalLcr = lcrValues[lcrValues.length - 1] || 0;

            var performance = 'Needs Improvement';
            if (totalScore >= 85) performance = 'Excellent — Bank Treasurer material';
            else if (totalScore >= 70) performance = 'Good — Solid risk awareness';
            else if (totalScore >= 55) performance = 'Developing — Review liquidity fundamentals';

            var insights = [];
            if (minLcr < 60) insights.push('The bank reached critical LCR levels below 60% — in practice, regulators would have intervened.');
            if (minLcr < 100 && finalLcr >= 100) insights.push('The contingency plan successfully restored the LCR above the regulatory minimum.');
            if (minLcr >= 100) insights.push('The bank maintained LCR compliance throughout — consider testing with higher stress levels.');
            if (totalScore >= 85) insights.push('Strong analytical performance — you identified key vulnerabilities and responded effectively.');
            if (totalScore < 55) insights.push('Review the Basel III liquidity framework and the interaction between market and funding liquidity.');

            var overallScore = Math.max(0, Math.min(100, Math.round(totalScore)));
            return {
                totalScore: totalScore,
                overallScore: overallScore,
                score: overallScore,
                minLcr: minLcr,
                finalLcr: finalLcr,
                performance: performance,
                insights: insights
            };
        }

